def factorial(n):
    """
    Calculate factorial of n.

    Args:
        n: Non-negative integer

    Returns:
        Factorial of n
    """
    if n < 0:
        raise ValueError("Factorial not defined for negative numbers")
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

